// Portao de aprovacao. Aprovado = sai ja · Agendado = so quando scheduled_at venceu.
// NUNCA dispara Fila. Sem photo_url/caption, pula (evita post quebrado no grupo).
//
// O n8n NAO monta legenda: le o `caption` pronto do Baserow e repassa cru.
// Quem escreve o texto e a skill /agenda. Mudou o formato da mensagem? Nao mexe aqui.
// JANELA: so dispara entre 9h e 21h (America/Sao_Paulo).
// Post de madrugada nao e lido por ninguem e ainda cheira a robo.
// Fora da janela a fila espera: ninguem perde o lugar, so sai mais tarde.
//
// TIMEZONE: NAO usar new Date().getHours() - o container do n8n roda em UTC,
// e 9-21 UTC seria 6-18 no Brasil (dispararia as 6 da manha e pararia as 18h).
const horaBR = Number(new Date().toLocaleString('en-US', {
  timeZone: 'America/Sao_Paulo', hour: '2-digit', hour12: false
})) % 24;
if (horaBR < 9 || horaBR >= 21) return [];

const cfg = $('Config').first().json;
const now = new Date().toISOString();
const rows = ($input.first().json.results) || [];
const out = [];
for (const r of rows) {
  const st = (r.status && r.status.value) ? r.status.value : r.status;
  const due = st === 'Aprovado' || (st === 'Agendado' && r.scheduled_at && r.scheduled_at <= now);
  if (!due) continue;
  if (!r.photo_url || !r.caption) continue;
  // Payload do WAHA montado aqui: o file.url e aninhado e nao cabe em body keypair.
  // O WAHA busca a foto na URL publica do Baserow (o CDN do Mercari daria 403).
  out.push({ json: {
    row_id: r.id,
    payload: {
      session: cfg.waha_session,
      chatId: cfg.group_id,
      file: { url: r.photo_url },
      caption: r.caption
    }
  }});
}
// Quem espaca um a um agora e o Loop Over Items + o Wait aleatorio logo depois.
// Antes isto virava rajada (5 aprovados = 5 posts seguidos), que e exatamente o
// padrao que derruba conta no WEBJS.
//
// TETO DE SEGURANCA (nao e cadencia, e anti-duplicata): com Wait de ate 90s por
// peca, 20 pecas levariam 30min = o intervalo do proprio cron. A execucao seguinte
// comecaria com a primeira ainda rodando, veria as MESMAS linhas (que ainda nao
// viraram Disparado) e postaria tudo DE NOVO no grupo. 15 x 90s = 22min < 30min.
// O resto fica Aprovado e sai no proximo tick, sem perder o lugar.
return out.slice(0, 15);
